\documentclass[tikz,border=10pt]{standalone}
\usepackage{amsmath}
\usetikzlibrary{calc}
\begin{document}
\begin{tikzpicture}[line width=1.6pt, line join=round]
  % Scale s = 0.01995 cm per px; y flipped about 446 px
  \coordinate (A) at (4.649,7.880);
  \coordinate (E) at (4.649,1.057);
  \coordinate (D) at (1.125,4.574);
  \coordinate (C) at (4.668,4.098);
  \coordinate (M) at (2.432,6.494);
  \coordinate (O) at (3.250,4.541);

  % Right-angle mark vertex and its far corners
  \coordinate (V) at (2.773,6.125);
  \coordinate (P1) at (2.989,6.327);
  \coordinate (P2) at (3.191,6.110);
  \coordinate (P3) at (2.975,5.908);

  % Solid segments
  \draw (A) -- (E);
  \draw (E) -- (D);
  \draw (A) -- (D);
  \draw (D) -- (C);

  % Dashed segment through M to near C
  \draw[dashed] (2.462,6.462) -- (4.756,3.990);

  % Partial circle arcs (radius 1.53 cm about O)
  \draw ($(O)+(10:1.53)$) arc[start angle=10, end angle=33, radius=1.53];
  \draw ($(O)+(110:1.53)$) arc[start angle=110, end angle=162, radius=1.53];
  \draw ($(O)+(201:1.53)$) arc[start angle=201, end angle=271, radius=1.53];
  \draw ($(O)+(328:1.53)$) arc[start angle=328, end angle=351, radius=1.53];

  % Right-angle mark (one mark only)
  \draw (P1) -- (P2) -- (P3);

  % Labels
  \node[right] at (A) {\fontsize{16}{19.2}\selectfont $A$};
  \node[right] at (E) {\fontsize{16}{19.2}\selectfont $E$};
  \node[left]  at (D) {\fontsize{16}{19.2}\selectfont $D$};
  \node[right] at (C) {\fontsize{16}{19.2}\selectfont $C$};
  \node[left]  at (M) {\fontsize{16}{19.2}\selectfont $M$};
  \node[below right] at (O) {\fontsize{16}{19.2}\selectfont $O$};
\end{tikzpicture}
\end{document}

